 \end{array}\right| 
 \begin{array}{ l l }
 \text{окисник, відновлення}& \\
 \text{відновник, окиснення}& 
 \end{array}
 \end{gather*} 
 Відповідь: 7.

Пояснення 
 ТЕМА: Обчислення в хімії.
 Завдання скеровано на перевірку вміння обчислювати масу продукту реакції за масою реагенту.
 Дано: 
 m(\mathrm{CaCO_3})=25\ \text{г} 
 M(\mathrm{CaCO_3})=100\ \text{г/моль} 
 M(\mathrm{CaO})=56\ \text{г/моль} 
 Знайти: 
 m(\mathrm{CaO})\ -\ ? 
 \begin{gather*}
 \mathrm{CaCO_3=CaO+CO_2\uparrow}\\[7pt]
 n(\mathrm{CaO})=n(\mathrm{CaCO_3})\\[7pt]
 n(\mathrm{CaCO_3})=m(\mathrm{CaCO_3}):M(\mathrm{CaCO_3})\\[7pt]
 n(\mathrm{CaCO_3})=25\ \text{г}:100\ \text{г/моль}\\[7pt]
 n(\mathrm{CaCO_3})=0,25\ \text{моль}\\[7pt]
 m(\mathrm{CaO})=n(\mathrm{CaO})M(\mathrm{CaO})\\[7pt]
 m(\mathrm{CaO})=0,25\ \text{моль}\cdot 56\ \text{г/моль}\\[7pt]
 m(\mathrm{CaO})=14\ \text{г}
 \end{gather*} 
 Відповідь: 14.

Пояснення 
 ТЕМА: Обчислення в хімії. 
 Завдання скеровано на перевірку вміння розв’язувати комбіновані задачі.
 Дано: 
 m(\mathrm{C_2H_6})+m(\mathrm{CH_2O})=7,5\ \text{г} 
 V(\mathrm{CO_2})=8,96\ \text{л} 
 V_m(\mathrm{CO_2})=22,4\ \text{л/моль} 
 m(\mathrm{C_2H_6})=30\ \text{г/моль} 
 m(\mathrm{CH_2O})=30\ \text{г/моль} 
 Знайти: 
 \mathbf{\varphi}(\mathrm{CH_2O})\ -\ ? 
 \begin{gather*}
 \mathrm{2C_2H_6+7O_2\rightarrow 4CO_2+6H_2O}\\[7pt]
 \mathrm{CH_2O+O_2\rightarrow CO_2+H_2O}
 \end{gather*} 
 Молярні маси етану й метаналю однакові – 30 г/моль.
 \begin{gather*}
 n(\mathrm{C_2H_6})+n(\mathrm{CH_2O})=\frac{m(\mathrm{C_2H_6})+m(\mathrm{CH_2O})}{\left\langle M(\mathrm{C_2H_6,\ CH_2O}) \right\rangle}=\frac{7,5\ \text{г}}{30\ \text{г/моль}}=0,25\ \text{моль}\\[6pt]
 n(\mathrm{CO_2})_{\mathrm{CH_2O}}+n(\mathrm{CO_2})_{\mathrm{CH_2O}}=\frac{V(\mathrm{CO_2})}{V_m(\mathrm{CO_2})} =\frac{89,6\ \text{л}}{22,4\ \text{л/моль}}=0,4\ \text{моль}\\[6pt]
 n(\mathrm{CH_2O})=n(\mathrm{CO_2})_{\mathrm{CH_2O}}\ \text{приймемо за}\ x\ \text{моль}\\[6pt]
 n(\mathrm{C_2H_6})=\frac 12 n(\mathrm{CO_2})_{\mathrm{C_2H_6}}\\[6pt]
 n(\mathrm{C_2H_6})=\frac 12(0,4-x)\\[6pt]
 n(\mathrm{C_2H_6})=0,2-0,5x\\[7pt]
 x+(0,2-0,5x)=0,25\\[7pt]
 x=0,1\ (\text{моль})\\[6pt]
 \mathbf{\varphi}(\mathrm{CH_2O}) =\frac{n(\mathrm{CH_2O})}{n(\mathrm{CH_2O})+n(\mathrm{C_2H_6})}\\[6pt]
 \mathbf{\varphi}(\mathrm{CH_2O})=\frac{0,1\ \text{моль}}{0,25\ \text{моль}}\\[6pt]
 \mathbf{\varphi}(\mathrm{CH_2O})=0,4\ (40\ \text{%})
 \end{gather*} 
 Відповідь: 40.
